}

class Product {
  +stockLevel : int
}

class Order {
  +orderDate : date
  +paymentDate : date
  +isPaidInFull : boolean
}

class OrderLine {
  +quantity : int
  +isShipped : boolean
}

class Invoice {
  +invoiceDate : date
  +isPaid : boolean
}

class Shipment {
  +status : string
}

class Delivery {
  +status : string
}

class Warehouse {
  +address : string
}

Customer "1" -- "*" Address : headOffice
Customer "1" -- "*" Address : deliveryAddress
Customer "1" -- "*" Order : places
Customer "1" -- "*" Invoice : receives

Order "1" *-- "1..*" OrderLine : contains
Order "1" -- "0..1" Invoice : generates

OrderLine "1" -- "1" Product : refers to
OrderLine "1" -- "0..1" Shipment : part of

Shipment "1" *-- "1..*" OrderLine : contains

Shipment "1" -- "0..1" Delivery : results in
Delivery "1" -- "*" Shipment : includes

Warehouse "*" -- "*" Customer : supplies
Warehouse "1" -- "*" Product : stocks

@enduml

